package dev.thefoolish.generated.anishelf;import android.content.*;import android.widget.*;public final class DetailActivity extends AppScreen{protected void render(){String id=getIntent().getStringExtra("id"),title=getIntent().getStringExtra("title"),summary=getIntent().getStringExtra("summary");int eps=getIntent().getIntExtra("episodes",0);title(title==null?"Anime":title);subtitle(summary==null||summary.length()==0?"No description supplied by provider.":summary);String key="fav_"+id;Button fav=button(store.flag(key)?"Remove from Library":"Add to Library");fav.setOnClickListener(v->{store.flag(key,!store.flag(key));fav.setText(store.flag(key)?"Remove from Library":"Add to Library");});body.addView(fav);body.addView(text("Episodes",18,true));if(eps<=0)subtitle("This provider did not supply an episode count.");for(int n=1;n<=Math.min(eps,100);n++){final int ep=n;Button b=button("Episode "+n+(store.number("progress_"+id+"_"+n)>0?" · Resume":""));b.setOnClickListener(v->{Intent i=new Intent(this,PlayerActivity.class);i.putExtra("id",id);i.putExtra("title",title);i.putExtra("episode",ep);startActivity(i);});body.addView(b);}nav();}}
